from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("text", "7. Символы и строки", "Читайте сообщения, обрабатывайте ASCII и не путайте байты с буквами.", [
        lesson("strings", "std::string и слова", "Храните текст переменной длины.",
            "Для текста подключите <string> и создайте std::string name;. Ввод std::cin >> name читает одно слово до пробельного разделителя; начальные пробелы пропускаются. Вывод строки работает через std::cout << name;. Оператор + соединяет строки: name + \"!\" создаёт новый текст, а += добавляет к существующему. Для двух строковых литералов напрямую + не подходит: хотя бы один операнд должен быть std::string.\n\nname.size() возвращает число элементов char, name.empty() проверяет пустоту. Строки можно сравнивать через == и !=. В этом уроке вводимые слова состоят из латинских букв. Для UTF-8 size() считает байты, а не обязательно видимые символы. Строка — самостоятельный объект; копирование std::string создаёт независимое значение.",
            program('std::string name;\nstd::cin >> name;\nstd::string message = "Hello, " + name + "!";\nstd::cout << message;', "iostream string"),
            "std::string не знает автоматически, какой человеческий язык хранится в байтах. В UTF-8 буквы могут занимать несколько char, а видимый знак иногда составлен из нескольких кодовых точек. Начальные ASCII-задачи честно ограничивают алфавит, поэтому длину здесь можно интерпретировать как число букв.",
            "Для слова используйте >>, для текста целой строки позже — getline. Уточняйте, какую именно длину считаете.", [
                code("greeting", "Приветствие пилота", 'Ввод: одно непустое слово name из латинских букв, до 30 букв. Выведите Hello, <name>! с одним пробелом после запятой.', 'std::string name;\nstd::cin >> name;\nstd::cout << "Hello, " << name << "!";', [("Vega", "Hello, Vega!"), ("A", "Hello, A!")], ["Кавычки вокруг name напечатали бы само имя переменной.", "Соедините фиксированные фрагменты и значение name в цепочке вывода."], "Вывод через << не требует собирать промежуточную строку.", headers="iostream string"),
                output("copy", "Независимая копия строки", 'std::string a = "Orb";\nstd::string b = a;\na += "it";\nstd::cout << a << " " << b;', "Orbit Orb", ["b скопирована до добавления it.", "Операция += меняет только a."], "Семантика значения сохраняется и для строки: копия не становится ссылкой на переменную.", headers="iostream string"),
                code("length", "Длина позывного", 'Ввод: одно слово из латинских букв длиной 1…50. Выведите количество букв и слово через пробел.', 'std::string name;\nstd::cin >> name;\nstd::cout << name.size() << " " << name;', [("Orion", "5 Orion"), ("X", "1 X")], ["Ограничение ASCII делает размер равным числу букв.", "Метод size вызывается с круглыми скобками."], "Утверждение о числе букв здесь опирается на условие об ASCII, а не на универсальное свойство string.", headers="iostream string"),
                choice("utf8", "Русский текст и size", 'Гарантирует ли std::string::size() количество видимых букв в произвольном UTF-8 тексте?', ["Да, в любой кодировке", "Нет, оно считает элементы char, для UTF-8 обычно байты", "Оно всегда возвращает 0 для русского текста"], 1, ["Один символ Unicode может занимать несколько байтов.", "string хранит последовательность char, не разбирая человеческие буквы."], "Для Unicode-ориентированных операций нужна отдельная корректная обработка кодировки."),
                code("pair", "Составной код рейса", 'Ввод: два латинских слова prefix и suffix длиной 1…20. Соберите строку prefix-suffix через +, выведите её и длину на отдельных строках.', 'std::string prefix, suffix;\nstd::cin >> prefix >> suffix;\nstd::string route = prefix + "-" + suffix;\nstd::cout << route << "\\n" << route.size();', [("North Dock", "North-Dock\n10"), ("A B", "A-B\n3")], ["Дефис — отдельный строковый литерал.", "Сначала создайте route, затем используйте её и при выводе, и для size()."], "Соединение начинается со std::string prefix, поэтому оператор + имеет нужный строковый смысл.", headers="iostream string", difficulty=2)
            ], ["string", "конкатенация", "ASCII"]),
        lesson("getline", "Строка целиком", "Сохраните пробелы и пустую строку.",
            "std::getline(std::cin, line) читает текст до конца строки, сохраняет пробелы внутри и убирает завершающий разделитель новой строки из результата. Пустая входная строка даёт пустую std::string. Если перед getline читали число через >>, символ конца его строки обычно остаётся во входном потоке. Первый getline тогда может прочитать только этот пустой остаток.\n\nКогда формат говорит «число на отдельной строке, затем текст», после числа можно отбросить остаток его строки: std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\\n');. Для этого подключите <limits>. Это намеренно удаляет всё до конца первой строки. Не применяйте его вслепую, когда полезный текст находится на той же строке.\n\nstd::ws перед getline удаляет все начальные пробелы и пустые строки; это не универсальная замена, если они значимы.",
            program('std::string line;\nstd::getline(std::cin, line);\nstd::cout << "[" << line << "]";', "iostream string"),
            "Операции >> и getline используют один и тот же поток, но по-разному обрабатывают разделители. Ошибка «пустой ввод после числа» объясняется состоянием потока, а не случайным поведением компьютера. Выбор ignore или ws зависит от контракта: сохраняем ли ведущие пробелы и пустые строки.",
            "Для целой строки используйте getline. Перед смешиванием способов чтения явно решите судьбу остатка предыдущей строки.", [
                code("frame", "Сообщение в рамке", 'Ввод: одна строка из ASCII-символов длиной 0…80, пробелы значимы. Выведите её между [ и ], без добавочных пробелов.', 'std::string line;\nstd::getline(std::cin, line);\nstd::cout << "[" << line << "]";', [("air lock\n", "[air lock]"), ("\n", "[]"), ("  A \n", "[  A ]")], ["Обычный >> потерял бы всё после первого слова.", "Читайте getline без ws, чтобы сохранить начальные пробелы."], "Пустая строка — допустимые данные, а не отсутствие задания.", headers="iostream string"),
                output("space", "Пробелы принадлежат данным", 'std::string line = " A B ";\nstd::cout << line.size() << ":" << line;', "5: A B ", ["Посчитайте оба крайних пробела.", "size равен пяти, вывод сохраняет завершающий пробел."], "Точный ответ содержит пробел в конце; проверка вывода не удаляет значимые пробелы.", headers="iostream string"),
                code("numberline", "Номер и описание", 'Ввод: целое id (0…99) на первой строке, описание из ASCII на второй (0…80 символов, ведущие пробелы значимы). Выведите id, двоеточие и описание без добавленного пробела.', 'int id = 0;\nstd::cin >> id;\nstd::cin.ignore(std::numeric_limits<std::streamsize>::max(), \'\\n\');\nstd::string description;\nstd::getline(std::cin, description);\nstd::cout << id << ":" << description;', [("7\nair lock\n", "7:air lock"), ("0\n  A\n", "0:  A"), ("1\n\n", "1:")], ["После чтения числа нужно убрать конец первой строки.", "Используйте ignore до '\\n', затем getline без ws."], "ignore соответствует формату с отдельной первой строкой и не трогает начальные пробелы описания.", headers="iostream string limits", difficulty=2),
                choice("ws", "Когда ws мешает?", 'В условии значимы ведущие пробелы и пустые строки. Подходит ли getline(cin >> ws, line) без изменения смысла данных?', ["Да, ws ничего не удаляет", "Нет, ws пропускает начальные пробельные символы", "Нет, потому что getline запрещена после ws синтаксически"], 1, ["ws означает пропуск whitespace.", "Начальные пробелы могут быть частью сообщения."], "Выбор операции чтения должен сохранять информацию, обещанную условием."),
                code("two", "Две строки журнала", 'Ввод: ровно две ASCII-строки, каждая длиной 0…50, включая возможные пробелы. Выведите длины обеих через пробел. Не склеивайте строки.', 'std::string first, second;\nstd::getline(std::cin, first);\nstd::getline(std::cin, second);\nstd::cout << first.size() << " " << second.size();', [("air lock\nOK\n", "8 2"), ("\n \n", "0 1")], ["Два вызова getline прочитают две строки.", "Каждая строка имеет собственный size()."], "Перенос-разделитель не включается в длину строки.", headers="iostream string")
            ], ["getline", "потоки", "пробелы"]),
        lesson("characters", "Перебор символов", "Решайте текстовые задачи на явно заданном алфавите.",
            "Цикл for (char ch : text) перебирает элементы строки по значению. Переменная ch — копия текущего char; изменение ch не меняет text. Для построения результата создайте пустую std::string result и добавляйте подходящие символы через result += ch;. Это range-based for — перебор готовой последовательности без ручного индекса.\n\nВ этом уроке вход ограничен ASCII: латинскими буквами, цифрами и пробелами. Для цифры подходит проверка '0' <= ch && ch <= '9'. Стандарт гарантирует последовательность кодов десятичных цифр; ch - '0' даёт числовое значение цифры. Не распространяйте буквенные диапазоны на все кодировки и языки. Прямое сравнение ch == 'a' проверяет конкретный символ.",
            program('std::string text = "A2 B5";\nint sum = 0;\nfor (char ch : text) {\n    if (\'0\' <= ch && ch <= \'9\') { sum += ch - \'0\'; }\n}\nstd::cout << sum;', "iostream string"),
            "Не передавайте произвольный отрицательный char в std::isdigit и похожие функции: для них обычно нужно преобразование к unsigned char. В наших задачах явное сравнение цифр достаточно и не требует локали. Побайтовый разворот произвольного UTF-8 может разрушить кодировку, поэтому здесь не выдаём его за универсальный разворот текста.",
            "Перебирайте char по значению для чтения, собирайте новую строку для изменений. Проверяйте контракт алфавита.", [
                code("digits", "Цифры в сообщении", 'Ввод: одна ASCII-строка длиной 0…100. Выведите количество десятичных цифр в ней.', 'std::string text;\nstd::getline(std::cin, text);\nint count = 0;\nfor (char ch : text) {\n    if (\'0\' <= ch && ch <= \'9\') { ++count; }\n}\nstd::cout << count;', [("Dock 12, gate 3\n", "3"), ("\n", "0"), ("abc\n", "0")], ["Считайте символы-цифры, а не целые числа.", "Проверьте каждую ch двумя сравнениями с '0' и '9'."], "12 содержит две цифры, поэтому вместе с 3 получается три, а не два.", headers="iostream string"),
                output("copy", "Изменённая копия символа", 'std::string text = "ab";\nfor (char ch : text) {\n    ch = \'X\';\n    std::cout << ch;\n}\nstd::cout << ":" << text;', "XX:ab", ["ch объявлена по значению.", "Вывод внутри цикла читает новую ch, но text остаётся прежней."], "Для изменения элемента на месте понадобилась бы ссылка; здесь её намеренно нет.", headers="iostream string"),
                code("compact", "Уберите пробелы", 'Ввод: ASCII-строка длиной 0…100. Удалите только обычные пробелы (символ \' \'), сохранив порядок остальных символов. Выведите результат.', 'std::string text, result;\nstd::getline(std::cin, text);\nfor (char ch : text) {\n    if (ch != \' \') { result += ch; }\n}\nstd::cout << result;', [(" A B  C \n", "ABC"), ("   \n", ""), ("x-1\n", "x-1")], ["Создайте отдельную строку результата.", "Добавляйте ch только при ch != ' '."], "Требование относится к обычному пробелу, а не ко всем возможным пробельным символам.", headers="iostream string"),
                choice("bytes", "Опасный разворот", 'Почему побайтовый разворот произвольной строки UTF-8 может испортить русский текст?', ["Байты одного символа могут поменяться местами и перестать образовывать корректную последовательность", "Любая строка содержит только один байт", "В C++ нет строк с русским текстом"], 0, ["Один видимый символ не обязан равняться одному char.", "UTF-8 использует многобайтовые последовательности."], "Для Unicode-задачи нужно выбрать уровень: байты, кодовые точки или графемы, и использовать соответствующий алгоритм."),
                code("checksum", "Контрольная сумма сообщения", 'Ввод: одна ASCII-строка длиной 0…100. Выведите сумму значений всех десятичных цифр. Остальные символы игнорируйте.', 'std::string text;\nstd::getline(std::cin, text);\nint sum = 0;\nfor (char ch : text) {\n    if (\'0\' <= ch && ch <= \'9\') { sum += ch - \'0\'; }\n}\nstd::cout << sum;', [("A12-B9\n", "12"), ("no digits\n", "0"), ("007\n", "7")], ["Символ '7' не является числом 7 сам по себе.", "После проверки диапазона прибавляйте ch-'0'."], "Предварительная проверка не даёт случайно вычитать '0' из буквы или пробела.", headers="iostream string", difficulty=2)
            ], ["range for", "char", "обработка текста"]),
        lesson("searchtext", "Поиск и фрагменты", "Найдите разделитель и сформируйте ответ.",
            "text.find('-') возвращает позицию первого дефиса или специальное значение std::string::npos, если его нет. Позиции начинаются с 0. Для результата удобно auto position = text.find('-');: auto выводит тип из инициализатора, а не делает тип динамическим. Не сохраняйте npos в int и не проверяйте position<0.\n\ntext.substr(start, count) создаёт фрагмент от start длиной не больше count. text.substr(start) берёт остаток строки. start не должен быть больше size(); при start==size() результат пустой. Индексация text[index] читает элемент с заданным номером; для обычных элементов нужен index<size(). В этих задачах используем find и substr, проверяя наличие разделителя до вычисления position+1.\n\nstd::string::npos — маркер «не найдено», не допустимая позиция символа.",
            program('std::string text = "A-B";\nauto position = text.find(\'-\');\nif (position != std::string::npos) {\n    std::cout << text.substr(0, position) << " " << text.substr(position + 1);\n}', "iostream string"),
            "size() и find() используют беззнаковый размерный тип. Значение npos — специальное максимальное значение этого типа. Приведение к int скрывает смысл и может потерять диапазон. Правильная проверка — сравнение с std::string::npos в исходном типе.",
            "Сначала проверьте find на npos, затем используйте позицию. Индекс 0 — первый элемент, size() — уже за обычными элементами.", [
                code("split", "Префикс и хвост", 'Ввод: одна ASCII-строка длиной 0…100. Разделите её по первому дефису. Если дефис есть, выведите часть до него и часть после него на отдельных строках (вторая без завершающего переноса). Иначе выведите No separator.', 'std::string text;\nstd::getline(std::cin, text);\nauto pos = text.find(\'-\');\nif (pos == std::string::npos) {\n    std::cout << "No separator";\n} else {\n    std::cout << text.substr(0, pos) << "\\n" << text.substr(pos + 1);\n}', [("Dock-Air-Lock\n", "Dock\nAir-Lock"), ("ABC\n", "No separator"), ("-x\n", "\nx"), ("A-\n", "A\n")], ["find ищет первый дефис, остальные принадлежат хвосту.", "До разделителя берите substr(0,pos), после — substr(pos+1)."], "Пустая часть до или после разделителя допустима и не означает отсутствие разделителя.", headers="iostream string", difficulty=2),
                output("index", "Нулевая позиция", 'std::string text = "ORBIT";\nstd::cout << text[0] << " " << text.substr(1, 3);', "O RBI", ["Первый индекс равен 0.", "Три элемента с позиции 1 — R, B, I."], "В пределах ASCII индексы соответствуют символам в привычном смысле.", headers="iostream string"),
                code("contains", "Сигнал тревоги", 'Ввод: ASCII-строка длиной 0…100. Если она содержит точную подстроку SOS с учётом регистра, выведите Alert, иначе Quiet.', 'std::string text;\nstd::getline(std::cin, text);\nif (text.find("SOS") != std::string::npos) {\n    std::cout << "Alert";\n} else {\n    std::cout << "Quiet";\n}', [("xxSOSxx\n", "Alert"), ("sos\n", "Quiet"), ("\n", "Quiet")], ["find умеет искать не только char, но и строковый фрагмент.", "Найденная позиция может быть 0, поэтому не используйте её как bool."], "Сравнение с npos корректно и для совпадения в самом начале.", headers="iostream string"),
                choice("foundzero", "Ноль — тоже успех", 'Почему if (text.find("SOS")) неверно проверяет наличие SOS?', ["Совпадение в позиции 0 станет false, а npos обычно станет true", "find всегда возвращает bool", "Строки нельзя искать"], 0, ["find возвращает позицию или npos.", "Позиция первого символа равна нулю."], "Смысл проверки — не числовая истинность позиции, а её отличие от маркера отсутствия."),
                code("extension", "Расширение имени", 'Ввод: одно непустое ASCII-слово длиной до 100. Найдите первую точку. Если она есть, выведите хвост после неё (возможно пустой), иначе None. Имя может содержать несколько точек; используйте именно первую.', 'std::string name;\nstd::cin >> name;\nauto pos = name.find(\'.\');\nif (pos == std::string::npos) { std::cout << "None"; }\nelse { std::cout << name.substr(pos + 1); }', [("notes.txt", "txt"), ("archive.tar.gz", "tar.gz"), ("README", "None"), ("file.", "")], ["Условие специально говорит о первой, не последней точке.", "find('.') и substr(pos+1) достаточно после проверки npos."], "Реальные правила файловых расширений могут отличаться; здесь решается точно сформулированная задача над текстом.", headers="iostream string", difficulty=2)
            ], ["find", "substr", "индексы", "npos"])
    ])]
